 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: descuentoGlobal opcional (porcentaje entero 0-100) sobre el total de las líneas.
+export function calcularFactura(items, { descuentoGlobal } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const conDescuento = descuentoGlobal !== undefined;
+  if (conDescuento && (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100))
+    throw new RangeError("Descuento global inválido: debe ser un entero de 0 a 100");
+  const descuentoGlobalCentavos = conDescuento ? Math.round((subtotalCentavos * descuentoGlobal) / 100) : 0;
+  const totalCentavos = subtotalCentavos - descuentoGlobalCentavos;
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
-  return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  const resultado = { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  return conDescuento ? { subtotalCentavos, descuentoGlobalCentavos, ...resultado } : resultado;
 }

 // RF-001, RF-003: emite una factura válida y congelada.
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..2d2f502 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,84 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_RF006 = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006 P1: descuento global del 10 %", () => {
+  const f = calcularFactura(LINEAS_RF006, { descuentoGlobal: 10 });
+  assert.equal(f.descuentoGlobalCentavos, 1105);
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.ivaCentavos, 1293);
+  assert.equal(f.netoCentavos, 8652);
+});
+
+test("RF-006 P2: el 100 % se permite", () => {
+  const f = calcularFactura(LINEAS_RF006, { descuentoGlobal: 100 });
+  assert.equal(f.totalCentavos, 0);
+  assert.equal(f.ivaCentavos, 0);
+  assert.equal(f.netoCentavos, 0);
+});
+
+test("RF-006 P3: redondeo al centavo", () => {
+  const f = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 999 }], { descuentoGlobal: 15 });
+  assert.equal(f.descuentoGlobalCentavos, 150);
+  assert.equal(f.totalCentavos, 849);
+  assert.equal(f.ivaCentavos, 110);
+  assert.equal(f.netoCentavos, 739);
+});
+
+test("RF-006 P4: mitad de centavo redondea hacia arriba", () => {
+  const f = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 10 }], { descuentoGlobal: 5 });
+  assert.equal(f.descuentoGlobalCentavos, 1);
+  assert.equal(f.totalCentavos, 9);
+  assert.equal(f.ivaCentavos, 1);
+  assert.equal(f.netoCentavos, 8);
+});
+
+test("RF-006 P5: descuentoGlobal inválido lanza RangeError", () => {
+  for (const valor of [101, -1, 10.5, "10", NaN, Infinity, null]) {
+    assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: valor }), RangeError, `valor ${String(valor)}`);
+  }
+});
+
+test("RF-006 P6: sin descuentoGlobal el resultado es idéntico al actual", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepStrictEqual(calcularFactura(LINEAS_RF006), esperado);
+  assert.deepStrictEqual(calcularFactura(LINEAS_RF006, {}), esperado);
+  assert.deepStrictEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: undefined }), esperado);
+});
+
+test("RF-006 P7: con descuentoGlobal agrega solo dos claves", () => {
+  assert.deepStrictEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 10 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 1105,
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+  assert.deepStrictEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 0 }), {
+    subtotalCentavos: 11050,
+    descuentoGlobalCentavos: 0,
+    totalCentavos: 11050,
+    ivaCentavos: 1437,
+    netoCentavos: 9613,
+  });
+});
+
+test("RF-006 P8: emitirFactura no cambia y sigue congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_RF006, descuentoGlobal: 50 });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.estado, "emitida");
+  assert.equal(f.totalCentavos, 11050);
+  assert.equal(f.ivaCentavos, 1437);
+  assert.equal(f.netoCentavos, 9613);
+  assert.ok(!("descuentoGlobal" in f));
+  assert.ok(!("subtotalCentavos" in f));
+  assert.ok(!("descuentoGlobalCentavos" in f));
+});
+
